namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableValueVO;

trait TemplateVariableValueAccessor {
  private ?TemplateVariableValueVO $_value = null;
  public function getValue(): ?string
  {
    return $this->_value?->value();
  }
  public function value(): ?TemplateVariableValueVO
  {
    return $this->_value;
  }
  public function isValueChanged(?self $original = null): bool
  {
  return null !== $this->_value && !$this->_value->equals( $original?->_value );  }
  public function withValue(TemplateVariableValueVO|string|null $value): self
  {
    $copy = clone $this;
    $copy->_value = TemplateVariableValueVO::from( $value );
    return $copy;
  }
}